const usersRaw = $('Fetch All Users').first().json;
const productsRaw = $('Fetch Featured Products').first().json;

const users = Array.isArray(usersRaw) ? usersRaw : [];
const products = Array.isArray(productsRaw) ? productsRaw : [];

// Find inactive users (no login in 14+ days, based on updated_at or created_at)
const twoWeeksAgo = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000);
const inactiveUsers = users.filter(u => {
  const lastSeen = new Date(u.last_login || u.updated_at || u.created_at);
  return lastSeen < twoWeeksAgo;
});

// Build featured products HTML
const productCards = products.slice(0, 3).map(p =>
  `<div style='background:#f9f9f9;border-radius:8px;padding:12px;margin-bottom:10px;display:flex;gap:12px;align-items:center;'>
    <img src='${p.image_url}' style='width:64px;height:64px;object-fit:cover;border-radius:8px;flex-shrink:0;' />
    <div>
      <div style='font-weight:700;color:#333;font-size:0.9rem;'>${p.title}</div>
      <div style='color:#c8923a;font-weight:700;'>₹${p.price?.toLocaleString('en-IN')}</div>
      <div style='color:#888;font-size:0.78rem;'>${p.category} • ${p.condition}</div>
    </div>
  </div>`
).join('');

// Prepare email data for each inactive user
return inactiveUsers.map(u => ({
  json: {
    to: u.email,
    name: u.name || 'Student',
    subject: `👋 We miss you on NIRVANA MART!`,
    html: `
<div style='font-family:Segoe UI,sans-serif;max-width:600px;margin:0 auto;background:#f5f5f5;padding:24px;border-radius:12px;'>
  <div style='background:linear-gradient(135deg,#0a0a14,#1a102a);padding:32px;border-radius:10px;text-align:center;margin-bottom:24px;'>
    <h1 style='color:#e8b86d;margin:0;font-size:1.3rem;'>👋 Long time no see, ${u.name?.split(' ')[0] || 'there'}!</h1>
    <p style='color:rgba(255,255,255,0.7);margin:8px 0 0;'>New items have been listed since you last visited</p>
  </div>
  <div style='background:white;padding:24px;border-radius:10px;margin-bottom:16px;'>
    <h3 style='color:#333;margin:0 0 16px;'>🔥 Fresh Listings This Week</h3>
    ${productCards}
  </div>
  <div style='text-align:center;margin-bottom:20px;'>
    <a href='https://nirvana-mart.onrender.com/shop' style='display:inline-block;background:#c8923a;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:700;font-size:1rem;'>Browse All Products →</a>
  </div>
  <p style='color:#aaa;font-size:0.78rem;text-align:center;'>NIRVANA MART — Your Campus Marketplace</p>
</div>`
  }
}));
